<?php require_once '../config/auth.php';requireLogin();require_once '../config/database.php';$r=$conn->query("SELECT e.*,l.titulo,u.nome utilizador FROM emprestimos e JOIN livros l ON l.id=e.livro_id JOIN utilizadores u ON u.id=e.utilizador_id ORDER BY e.id DESC");?><!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Empréstimos</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="container"><div class="card"><a class="btn" href="../dashboard.php">Dashboard</a><a class="btn" href="criar.php">+ Empréstimo</a><h1>Empréstimos</h1></div><div class="card"><div class="table-wrap"><table><tr><th>Livro</th><th>Utilizador</th><th>Empréstimo</th><th>Prevista</th><th>Estado</th><th>Ação</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($x['titulo'])?></td><td><?=htmlspecialchars($x['utilizador'])?></td><td><?=$x['data_emprestimo']?></td><td><?=$x['data_prevista']?></td><td><?=$x['estado']?></td><td><?php if($x['estado']=='emprestado'):?><a class="btn" href="devolver.php?id=<?=$x['id']?>">Devolver</a><?php endif;?></td></tr><?php endwhile;?></table></div></div></div></body></html>
